def icon(name):
 return '<svg class="icon" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+ICONS[name]+'</svg>'

def render(lang):
 def t(th,en): return th if lang=='th' else en
 home='./' if lang=='th' else './en.html'
 alt='./en.html' if lang=='th' else './'
